package api

// Matrix is the authorisation matrix of the API, one row per operation: who may call it. Every operation has a row, and the test
// TestEveryOperationHasARowInTheAuthorisationMatrix fails the build for one that has none (closed by default). The matrix of
// PRD-002 Appendix B, per role and per field, arrives with the roles slice of p1-nemura-platform; the first rows are the operations that need no
// sign-in and show no organisation's data, then the ones any signed-in person may call.
var Matrix = map[string]string{ // #nosec G101 -- operation names and who may call them, not credentials
	"GET /v1/info":                                    "anyone",
	"GET /v1/errors":                                  "anyone",
	"GET /v1/errors/{code}":                           "anyone",
	"GET /v1/sign-in":                                 "anyone",
	"GET /v1/session":                                 "signed in (any role)",
	"POST /v1/passkeys/registration":                  "signed in (any role), for themselves",
	"POST /v1/passkeys":                               "signed in (any role), for themselves",
	"POST /v1/session/step-up":                        "signed in (any role), for themselves",
	"POST /v1/session/step-up/confirm":                "signed in (any role), for themselves",
	"POST /v1/api-clients":                            "Owner, with a fresh passkey confirmation",
	"GET /v1/api-clients":                             "Owner",
	"DELETE /v1/api-clients/{id}":                     "Owner, with a fresh passkey confirmation",
	"GET /v1/features":                                "HR officer, HR administrator, Payroll administrator, Administrator, Owner",
	"PUT /v1/features/{feature}":                      "HR administrator, Owner",
	"PUT /v1/people/{id}/nric":                        "HR officer, HR administrator",
	"GET /v1/people/{id}/secrets/{field}":             "by Appendix B's NRIC and bank rows: HR officer masked; HR administrator, Payroll administrator and Owner as the matrix says; the person their own in full; everyone else nothing",
	"POST /v1/people/{id}/work-passes":                "HR officer, HR administrator",
	"GET /v1/people/{id}/work-passes":                 "HR officer, HR administrator, Payroll administrator, Owner",
	"POST /v1/people/{id}/dependants":                 "the person themselves, HR officer, HR administrator",
	"GET /v1/people/{id}/dependants":                  "by Appendix B's dependants row: HR officer in full, Payroll administrator where pay depends on it, the person their own; everyone else nothing",
	"POST /v1/people/{id}/documents":                  "HR officer, HR administrator",
	"GET /v1/people/{id}/documents":                   "the roles each document names as viewers, and the person for those naming employee",
	"GET /v1/people/{id}/documents/{doc}":             "the roles each document names as viewers, and the person for those naming employee",
	"POST /v1/people/{id}/bank-account-changes":       "the person themselves (an employee proposes for their own account only)",
	"POST /v1/bank-account-changes/{id}/decision":     "HR administrator, Payroll administrator, Owner; never the proposer nor the account's person",
	"POST /v1/bank-account-changes/{id}/confirm":      "the person whose account it is, with a fresh passkey confirmation",
	"GET /v1/bank-account-changes/{id}":               "the person it concerns and the approvers",
	"GET /v1/packs":                                   "HR officer, HR administrator, Payroll administrator, Administrator, Owner",
	"POST /v1/packs/{version}/acceptances":            "HR administrator, Owner",
	"POST /v1/packs/{version}/decisions":              "HR administrator, Owner",
	"PUT /v1/policy":                                  "HR administrator, Owner",
	"GET /v1/policy":                                  "HR officer, HR administrator, Payroll administrator, Administrator, Owner",
	"GET /v1/checks":                                  "HR officer, HR administrator, Payroll administrator, Administrator, Owner",
	"GET /v1/people/{id}/leave/{year}":                "the person themselves and a line manager for their reports; HR officer, HR administrator, Payroll administrator, Owner for anyone (Appendix B: Leave requests)",
	"GET /v1/me/leave/{year}":                         "signed in (any role), for themselves",
	"POST /v1/me/leave-requests/preview":              "signed in (any role), for themselves",
	"POST /v1/me/leave-requests":                      "signed in (any role), for themselves",
	"GET /v1/leave-requests":                          "signed in (any role): their own; a line manager their reports'; HR officer, HR administrator, Payroll administrator and Owner everyone's",
	"GET /v1/leave-calendar":                          "signed in (any role): themselves, their team as Away; a line manager their reports' types; the people team everyone's; sick leave only to the person and HR officer and HR administrator",
	"GET /v1/leave-requests/{id}":                     "the same scope: a request outside it is not found",
	"POST /v1/leave-requests/{id}/decision":           "a line manager for their reports; HR officer, HR administrator, Owner for anyone; never the person's own",
	"POST /v1/leave-requests/{id}/cancellation":       "the person themselves",
	"POST /v1/leave/settlement":                       "HR officer, HR administrator",
	"POST /v1/me/sick-leave":                          "signed in (any role), for themselves",
	"GET /v1/sick-leave":                              "signed in (any role): their own; HR officer and HR administrator everyone's (Appendix B: Medical certificates and notes); nobody else's",
	"POST /v1/sick-leave/{id}/certificate":            "the person themselves; HR officer and HR administrator for anyone",
	"POST /v1/sick-leave/{id}/verification":           "HR officer and HR administrator, never for their own certificate",
	"POST /v1/people/{id}/government-paid-leave":      "HR officer, HR administrator",
	"GET /v1/government-paid-leave":                   "HR officer, HR administrator, Payroll administrator, Owner (Appendix B: Leave requests)",
	"POST /v1/government-paid-leave/{id}/claims":      "HR officer, HR administrator",
	"POST /v1/government-paid-claims/{id}/events":     "HR officer, HR administrator",
	"POST /v1/me/flexible-work-requests":              "signed in (any role), for themselves",
	"GET /v1/flexible-work-requests":                  "signed in (any role): their own; HR officer, HR administrator and Owner everyone's",
	"POST /v1/flexible-work-requests/{id}/reply":      "HR officer, HR administrator, Owner; never to their own request",
	"POST /v1/flexible-work-requests/{id}/withdrawal": "the person themselves",
	"POST /v1/me/overtime":                            "signed in (any role), for themselves: a Part IV employee only",
	"GET /v1/overtime":                                "signed in (any role): their own; a line manager their reports'; HR officer, HR administrator, Payroll administrator and Owner everyone's",
	"POST /v1/overtime/{id}/decision":                 "a line manager for their reports; HR officer, HR administrator, Owner for anyone; never the person's own",
	"GET /v1/pay-inputs":                              "HR officer, HR administrator, Payroll administrator, Owner",
	"POST /v1/sick-leave/{id}/unpaid-decision":        "HR officer, HR administrator",
	"POST /v1/people/{id}/leave/{year}/encashment":    "HR officer, HR administrator",
	"POST /v1/leave/accruals":                         "HR officer, HR administrator",
	"GET /v1/leave/accruals":                          "HR officer, HR administrator, Payroll administrator, Owner",
	"POST /v1/leave/accruals/approval":                "HR officer, HR administrator, Owner; never the draft they made",
	"GET /v1/people/{id}/availability":                "the person themselves and a line manager for their reports; HR officer, HR administrator, Payroll administrator, Owner for anyone",
	"PUT /v1/people/{id}/working-pattern":             "HR officer, HR administrator",
	"POST /v1/people/{id}/leave/{year}/annual-grant":  "HR officer, HR administrator",
	"POST /v1/people/{id}/leave/{year}/carry-forward": "HR officer, HR administrator",
	"GET /v1/people":                                  "signed in (any role): the directory shows nothing restricted",
	"GET /v1/people/{id}":                             "HR officer, HR administrator, Payroll administrator, Owner (any person, with the classification); the person themselves and a line manager for their reports (without it)",
	"POST /v1/people":                                 "HR officer, HR administrator",
	"PUT /v1/people/{id}":                             "HR officer, HR administrator",
	"POST /v1/people/{id}/job":                        "HR officer, HR administrator",
	"POST /v1/people/{id}/classification":             "HR officer, HR administrator",
}
